CREATE TABLE plans(id text PRIMARY KEY, name text NOT NULL, currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), amount bigint NOT NULL CHECK(amount>=0), months int NOT NULL CHECK(months>0), active boolean NOT NULL DEFAULT true);
INSERT INTO plans VALUES ('starter-v1','Starter','INR',49900,1,true),('professional-v1','Professional','INR',149900,1,true),('annual-v1','Professional annual','INR',1499000,12,true);
CREATE TABLE subscriptions(id uuid PRIMARY KEY, tenant text NOT NULL, customer text NOT NULL, plan text NOT NULL REFERENCES plans, currency text NOT NULL, amount bigint NOT NULL CHECK(amount>=0), months int NOT NULL CHECK(months>0), quantity int NOT NULL CHECK(quantity>0), state text NOT NULL CHECK(state IN ('INCOMPLETE','TRIALING','ACTIVE','PAST_DUE','PAUSED','CANCELLED')), anchor timestamp NOT NULL, zone text NOT NULL, cycle bigint NOT NULL DEFAULT 0, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, cancel_at_end boolean NOT NULL DEFAULT false, UNIQUE(tenant,id));
CREATE TABLE operations(tenant text NOT NULL, kind text NOT NULL, key text NOT NULL, fingerprint text NOT NULL, result uuid NOT NULL, PRIMARY KEY(tenant,kind,key));
CREATE TABLE jobs(id uuid PRIMARY KEY, subscription uuid NOT NULL REFERENCES subscriptions, due timestamptz NOT NULL, lease_until timestamptz, attempts int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'READY');
CREATE INDEX jobs_due ON jobs(due) WHERE status='READY';
CREATE SEQUENCE invoice_number;
CREATE TABLE invoices(id uuid PRIMARY KEY, tenant text NOT NULL, subscription uuid NOT NULL REFERENCES subscriptions, cycle bigint NOT NULL, number bigint NOT NULL UNIQUE DEFAULT nextval('invoice_number'), currency text NOT NULL, total bigint NOT NULL CHECK(total>=0), paid bigint NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=total), credit bigint NOT NULL DEFAULT 0 CHECK(credit>=0 AND credit+paid<=total), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('OPEN','PAID','VOID')), UNIQUE(subscription,cycle));
CREATE TABLE payments(id uuid PRIMARY KEY, tenant text NOT NULL, invoice uuid NOT NULL REFERENCES invoices UNIQUE, amount bigint NOT NULL CHECK(amount>=0), refunded bigint NOT NULL DEFAULT 0 CHECK(refunded>=0 AND refunded<=amount), state text NOT NULL CHECK(state IN ('PENDING','UNKNOWN','SUCCEEDED','DECLINED')), scenario text NOT NULL DEFAULT 'SUCCESS', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_payments(id uuid PRIMARY KEY, amount bigint NOT NULL, state text NOT NULL);
CREATE TABLE refunds(id uuid PRIMARY KEY, tenant text NOT NULL, payment uuid NOT NULL REFERENCES payments, amount bigint NOT NULL CHECK(amount>0));
CREATE TABLE credits(id uuid PRIMARY KEY, tenant text NOT NULL, invoice uuid NOT NULL REFERENCES invoices, amount bigint NOT NULL CHECK(amount>0), reason text NOT NULL);
CREATE TABLE usage_events(tenant text NOT NULL, event_id text NOT NULL, subscription uuid NOT NULL REFERENCES subscriptions, quantity bigint NOT NULL CHECK(quantity>=0), occurred_at timestamptz NOT NULL, PRIMARY KEY(tenant,event_id));
CREATE TABLE journals(id uuid PRIMARY KEY, tenant text NOT NULL, source text NOT NULL UNIQUE, currency text NOT NULL, debit_account text NOT NULL, credit_account text NOT NULL, amount bigint NOT NULL CHECK(amount>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(debit_account<>credit_account));
CREATE TABLE outbox(id uuid PRIMARY KEY, tenant text NOT NULL, type text NOT NULL, aggregate_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE discrepancies(id uuid PRIMARY KEY, tenant text NOT NULL, reference uuid NOT NULL, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reference,kind));
CREATE FUNCTION immutable_financial() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable financial record'; END $$;
CREATE TRIGGER immutable_journal BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION immutable_financial();
CREATE FUNCTION protect_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.total,NEW.currency,NEW.number,NEW.subscription,NEW.cycle,NEW.period_start,NEW.period_end) IS DISTINCT FROM (OLD.total,OLD.currency,OLD.number,OLD.subscription,OLD.cycle,OLD.period_start,OLD.period_end) THEN RAISE EXCEPTION 'Finalized invoice is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_invoice BEFORE UPDATE ON invoices FOR EACH ROW EXECUTE FUNCTION protect_invoice();
